/**
 * Standard import format v1 (Phase 2). Single source of truth for column
 * rules; mirrors the "Kamus Kolom" in samples/phase-2/Template_Standar_Impor.xlsx
 * (generated by scripts/samples/generate_phase2_samples.py).
 */
export const MARKETPLACE_CHANNELS = ["shopee", "tiktok_shop", "tokopedia"] as const;
export type MarketplaceChannel = (typeof MARKETPLACE_CHANNELS)[number];

/** Where a sale came from (kinerja_touchpoint). */
export const TOUCHPOINTS = ["organik", "iklan", "afiliasi", "live", "video"] as const;
export type Touchpoint = (typeof TOUCHPOINTS)[number];
export const TOUCHPOINT_LABELS: Record<Touchpoint, string> = {
  organik: "Organik",
  iklan: "Iklan",
  afiliasi: "Afiliasi",
  live: "Live",
  video: "Video",
};

export type ColumnType =
  | "date" // YYYY-MM-DD
  | "month" // YYYY-MM
  | "channel"
  | "touchpoint"
  | "text"
  | "integer"; // whole number, no separators/abbreviations

export type ColumnSpec = {
  name: string;
  label: string;
  type: ColumnType;
  required: boolean;
  /** Inclusive lower bound for integers (default 0). */
  min?: number;
  maxLength?: number;
  /** Date column that must not be after the upload date. */
  notFuture?: boolean;
  /** Text format rule (checked after trimming). */
  pattern?: { re: RegExp; hint: string };
};

export type TemplateKey =
  | "kinerja_toko_harian"
  | "kinerja_produk_harian"
  | "target_bulanan"
  | "master_listing"
  | "kinerja_touchpoint"
  | "meta_ads_harian"
  | "penjualan_hsl"
  | "iklan_marketplace_harian";

/** import_batches.report_type values. */
export type DbReportType =
  | "marketplace_sales_daily"
  | "marketplace_product_performance"
  | "sales_target"
  | "channel_listing_master"
  | "touchpoint_performance"
  | "meta_ads_performance"
  | "shopee_hsl_affiliate"
  | "marketplace_ads_daily";

export type TemplateSpec = {
  key: TemplateKey;
  title: string;
  dbReportType: DbReportType;
  columns: ColumnSpec[];
  /** Natural key columns (unique within a file). */
  keyColumns: string[];
  /** Column holding the period (for batch period_start/period_end). */
  periodColumn?: string;
};

